-- Synthetic nsys SQLite export (trimmed), dumped to SQL text for attachment.
-- Restore: python3 -c "import sqlite3;c=sqlite3.connect('trace.sqlite');c.executescript(open('trace.sql').read());c.commit()"
-- Timestamps are ns. Each kernel row is a coalesced group of per-layer kernels (trace was down-sampled).
PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE StringIds (id INTEGER PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE CUPTI_ACTIVITY_KIND_KERNEL (start INTEGER NOT NULL, end INTEGER NOT NULL, deviceId INTEGER NOT NULL, streamId INTEGER NOT NULL, correlationId INTEGER, shortName INTEGER NOT NULL);
CREATE TABLE CUPTI_ACTIVITY_KIND_RUNTIME (start INTEGER NOT NULL, end INTEGER NOT NULL, nameId INTEGER NOT NULL, correlationId INTEGER);
CREATE TABLE NVTX_EVENTS (start INTEGER NOT NULL, end INTEGER, text TEXT, textId INTEGER);
COMMIT;
